function isPlainObject(value) {
  if (value === null || typeof value !== 'object') return false;
  const prototype = Object.getPrototypeOf(value);
  return prototype === Object.prototype || prototype === null;
}

function cloneEntry(entry) {
  if (!isPlainObject(entry) || typeof entry.text !== 'string' ||
      !Number.isSafeInteger(entry.sequence) || entry.sequence < 0) {
    throw new TypeError('invalid journal entry');
  }
  return { text: entry.text, sequence: entry.sequence };
}

function cloneEntries(entries) {
  if (!Array.isArray(entries)) throw new TypeError('entries must be an array');
  return entries.map(cloneEntry);
}

function reduceJournal(state, action) {
  const current = state === undefined ? { open: false, entries: [] } : state;
  if (action === null || typeof action !== 'object' || typeof action.type !== 'string') {
    throw new TypeError('action must have a string type');
  }

  switch (action.type) {
    case 'OPEN_JOURNAL':
      return { open: true, entries: cloneEntries(current.entries) };
    case 'CLOSE_JOURNAL':
      return { open: false, entries: [] };
    case 'LOAD_ENTRIES':
      return { open: current.open, entries: cloneEntries(action.entries) };
    case 'ADD_ENTRY':
      cloneEntry(action.entry);
      return { open: current.open, entries: [...cloneEntries(current.entries), action.entry] };
    default:
      return current;
  }
}

module.exports = reduceJournal;

