'use strict';
const assert = require('node:assert');
const reduceJournal = require('./solution');
assert.strictEqual(typeof reduceJournal, 'function');

assert.throws(() => reduceJournal(undefined, undefined), TypeError);
assert.throws(() => reduceJournal(undefined, null), TypeError);
assert.throws(() => reduceJournal(undefined, {}), TypeError);
assert.throws(() => reduceJournal(undefined, { type: 1 }), TypeError);
assert.deepStrictEqual(reduceJournal(undefined, { type: 'UNKNOWN' }), { open: false, entries: [] });

const original = { open: false, entries: [{ text: 'first', sequence: 0 }] };
const opened = reduceJournal(original, { type: 'OPEN_JOURNAL' });
assert.deepStrictEqual(opened, { open: true, entries: [{ text: 'first', sequence: 0 }] });
assert.notStrictEqual(opened, original);
assert.notStrictEqual(opened.entries, original.entries);
assert.notStrictEqual(opened.entries[0], original.entries[0]);
opened.entries[0].text = 'changed';
assert.strictEqual(original.entries[0].text, 'first');
original.entries[0].text = 'source changed';
assert.strictEqual(opened.entries[0].text, 'changed');

const loadEntry = { text: '', sequence: Number.MAX_SAFE_INTEGER };
const loadAction = { type: 'LOAD_ENTRIES', entries: [loadEntry, { text: 'next', sequence: 2 }] };
const loaded = reduceJournal(opened, loadAction);
assert.deepStrictEqual(loaded, { open: true, entries: [{ text: '', sequence: Number.MAX_SAFE_INTEGER }, { text: 'next', sequence: 2 }] });
assert.notStrictEqual(loaded.entries, loadAction.entries);
assert.notStrictEqual(loaded.entries[0], loadEntry);
loadEntry.text = 'mutated';
loadAction.entries.push({ text: 'late', sequence: 3 });
assert.strictEqual(loaded.entries.length, 2);
assert.strictEqual(loaded.entries[0].text, '');

const addEntry = { text: 'added', sequence: 4 };
const added = reduceJournal(loaded, { type: 'ADD_ENTRY', entry: addEntry });
assert.deepStrictEqual(added.entries.map((entry) => entry.text), ['', 'next', 'added']);
assert.notStrictEqual(added.entries[0], loaded.entries[0]);
assert.notStrictEqual(added.entries[2], addEntry);
addEntry.text = 'mutated';
loaded.entries[0].text = 'old mutation';
assert.deepStrictEqual(added.entries.map((entry) => entry.text), ['', 'next', 'added']);

const closed = reduceJournal(added, { type: 'CLOSE_JOURNAL' });
assert.deepStrictEqual(closed, { open: false, entries: [] });
assert.notStrictEqual(closed, added);
const emptyLoaded = reduceJournal(closed, { type: 'LOAD_ENTRIES', entries: [] });
assert.deepStrictEqual(emptyLoaded, { open: false, entries: [] });
assert.notStrictEqual(emptyLoaded.entries, closed.entries);

for (const entries of [null, {}, [null], [{ text: 1, sequence: 0 }], [{ text: 'x', sequence: -1 }], [{ text: 'x', sequence: 1.5 }], [{ text: 'x', sequence: Number.MAX_SAFE_INTEGER + 1 }]]) {
  assert.throws(() => reduceJournal(closed, { type: 'LOAD_ENTRIES', entries }), TypeError);
}
for (const entry of [null, { text: 'x' }, { text: 1, sequence: 0 }, { text: 'x', sequence: -1 }]) {
  assert.throws(() => reduceJournal(closed, { type: 'ADD_ENTRY', entry }), TypeError);
}
const identityState = { open: true, entries: [] };
assert.strictEqual(reduceJournal(identityState, { type: 'NOT_HANDLED', entry: null }), identityState);

